/*
 * Negotiates with client the telnet session options.
 * This routine will be invoked after new session is
 * established and before the inter-activate begin.
 */
static BOOL __negotiate(const int client_sock)
{
	char cmd_and_opt[3];
	int result = -1;
	BOOL bResult = FALSE;

	/* Tell client we WILL echo (server will handle echoing) */
	cmd_and_opt[0] = NVT_IAC;
	cmd_and_opt[1] = NVT_CMD_WILL;
	cmd_and_opt[2] = NVT_OPTION_ECHO;
	result = send(client_sock, cmd_and_opt, 3, 0);
	if (result < 0)
	{
		_hx_printf("[%s]send WILL echo fail[%d]\r\n", __func__, result);
		goto __TERMINAL;
	}

	/* Tell client we WONT suppress Go Ahead */
	cmd_and_opt[0] = NVT_IAC;
	cmd_and_opt[1] = NVT_CMD_WONT;
	cmd_and_opt[2] = NVT_OPTION_CLOCKID; /* Suppress Go Ahead option */
	result = send(client_sock, cmd_and_opt, 3, 0);
	if (result < 0)
	{
		_hx_printf("[%s]send WONT suppress GA fail[%d]\r\n", __func__, result);
		goto __TERMINAL;
	}

	/* Ask client to DO terminal type */
	cmd_and_opt[0] = NVT_IAC;
	cmd_and_opt[1] = NVT_CMD_DO;
	cmd_and_opt[2] = NVT_OPTION_TERMINAL_TYPE;
	result = send(client_sock, cmd_and_opt, 3, 0);
	if (result < 0)
	{
		_hx_printf("[%s]send DO terminal type fail[%d]\r\n", __func__, result);
		goto __TERMINAL;
	}

	/* Ask client to DO window size */
	cmd_and_opt[0] = NVT_IAC;
	cmd_and_opt[1] = NVT_CMD_DO;
	cmd_and_opt[2] = NVT_OPTION_WINDOW_SIZE;
	result = send(client_sock, cmd_and_opt, 3, 0);
	if (result < 0)
	{
		_hx_printf("[%s]send DO window size fail[%d]\r\n", __func__, result);
		goto __TERMINAL;
	}

	bResult = TRUE;

__TERMINAL:
	return bResult;
}

/* 
 * Handler to handle the incoming commands and 
 * options from client. 
 * Any command and it's associated options could arrive
 * in the stream of data, with IAC in front of them. All
 * these bytes are posted to this routine to process.
 * The bytes in buffer(iac) processed by this routine is
 * returned, so the caller could continue to process
 * the remaining bytes in buffer.
 * @length denotes the buffer(iac)'s length.
 */
static int __cmd_opt_handler(int client_sock, unsigned char* iac, int length)
{
	int index = 0;
	char response[3];

	BUG_ON(NVT_IAC != iac[index++]);

	/* For debugging. */
	//_hx_printf("[%s]telnet cmd[%d], option[%d]\r\n", __func__,
	//	iac[1], iac[2]);

	while (index < length)
	{
		/* Second byte is command value. */
		switch (iac[index++])
		{
		case NVT_CMD_WILL:
			if (index >= length) break;
			switch (iac[index++])
			{
			case NVT_OPTION_ECHO:
				/* Client wants to enable echo, we agree */
				response[0] = NVT_IAC;
				response[1] = NVT_CMD_DO;
				response[2] = NVT_OPTION_ECHO;
				send(client_sock, response, 3, 0);
				_hx_printf("[client WILL echo]\r\n");
				break;
			case NVT_OPTION_TERMINAL_TYPE:
				/* Client wants to negotiate terminal type */
				response[0] = NVT_IAC;
				response[1] = NVT_CMD_DO;
				response[2] = NVT_OPTION_TERMINAL_TYPE;
				send(client_sock, response, 3, 0);
				break;
			default:
				/* Reject other options */
				response[0] = NVT_IAC;
				response[1] = NVT_CMD_DONT;
				response[2] = iac[index - 1];
				send(client_sock, response, 3, 0);
				break;
			}
			break;
			
		case NVT_CMD_WONT:
			if (index >= length) break;
			switch (iac[index++])
			{
			case NVT_OPTION_ECHO:
				_hx_printf("[client WONT echo]\r\n");
				break;
			default:
				break;
			}
			break;
			
		case NVT_CMD_DO:
			if (index >= length) break;
			switch (iac[index++])
			{
			case NVT_OPTION_ECHO:
				/* Client wants us to echo */
				response[0] = NVT_IAC;
				response[1] = NVT_CMD_WILL;
				response[2] = NVT_OPTION_ECHO;
				send(client_sock, response, 3, 0);
				break;
			default:
				/* Reject other options */
				response[0] = NVT_IAC;
				response[1] = NVT_CMD_WONT;
				response[2] = iac[index - 1];
				send(client_sock, response, 3, 0);
				break;
			}
			break;
			
		case NVT_CMD_DONT:
			if (index >= length) break;
			switch (iac[index++])
			{
			case NVT_OPTION_ECHO:
				/* Client doesn't want us to echo */
				response[0] = NVT_IAC;
				response[1] = NVT_CMD_WONT;
				response[2] = NVT_OPTION_ECHO;
				send(client_sock, response, 3, 0);
				break;
			default:
				break;
			}
			break;
			
		case NVT_CMD_SB:  /* Subnegotiation */
			if (index >= length) break;
			{
				int opt = iac[index++];
				int sb_end = index;
				
				/* Find SE (Subnegotiation End) */
				while (sb_end < length && iac[sb_end] != NVT_CMD_SE) {
					sb_end++;
				}
				
				if (opt == NVT_OPTION_TERMINAL_TYPE && sb_end < length) {
					/* Terminal type subnegotiation */
					if (index < sb_end && iac[index] == 0) { /* IS command */
						/* Send terminal type */
						unsigned char sb_response[] = {
							NVT_IAC, NVT_CMD_SB, NVT_OPTION_TERMINAL_TYPE,
							0, /* IS */
							'v', 't', '1', '0', '0', /* vt100 terminal */
							NVT_IAC, NVT_CMD_SE
						};
						send(client_sock, sb_response, sizeof(sb_response), 0);
					}
				}
				
				index = sb_end + 1; /* Skip SE */
			}
			break;
			
		case NVT_CMD_IP:  /* Interrupt Process */
		case NVT_CMD_AO:  /* Abort Output */
		case NVT_CMD_AYT: /* Are You There */
		case NVT_CMD_EC:  /* Erase Character */
		case NVT_CMD_EL:  /* Erase Line */
		case NVT_CMD_GA:  /* Go Ahead */
		case NVT_CMD_NOP: /* No Operation */
			/* These are single-byte commands, no option byte */
			break;
			
		default:
			/* Unknown command, skip it */
			if (index < length) index++;
			break;
		}
	}
	return index;
}

/*
 * Helper function to handle escape sequences (control keys).
 * Returns the number of bytes consumed from the buffer, or 0 if
 * it's not a complete escape sequence yet.
 */
static int __handle_escape_sequence(int client_sock, unsigned char* buffer, int length, int start_idx)
{
	__DEVICE_MESSAGE dmsg;
	
	if (length - start_idx < 2) {
		/* Not enough data for a complete sequence */
		return 0;
	}
	
	/* Check for common escape sequences */
	if (buffer[start_idx] == ESC_KEY) {
		/* ESC sequence */
		if (length - start_idx >= 3) {
			/* Check for CSI sequences (ESC [) */
			if (buffer[start_idx + 1] == '[') {
				switch (buffer[start_idx + 2]) {
				case 'A':  /* Up arrow */
					dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
					dmsg.dwDevMsgParam = VK_UPARROW;
					DeviceInputManager.SendDeviceMessage(
						(__COMMON_OBJECT*)&DeviceInputManager,
						&dmsg, NULL);
					return 3;
				case 'B':  /* Down arrow */
					dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
					dmsg.dwDevMsgParam = VK_DOWNARROW;
					DeviceInputManager.SendDeviceMessage(
						(__COMMON_OBJECT*)&DeviceInputManager,
						&dmsg, NULL);
					return 3;
				case 'C':  /* Right arrow */
					dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
					dmsg.dwDevMsgParam = VK_RIGHTARROW;
					DeviceInputManager.SendDeviceMessage(
						(__COMMON_OBJECT*)&DeviceInputManager,
						&dmsg, NULL);
					return 3;
				case 'D':  /* Left arrow */
					dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
					dmsg.dwDevMsgParam = VK_LEFTARROW;
					DeviceInputManager.SendDeviceMessage(
						(__COMMON_OBJECT*)&DeviceInputManager,
						&dmsg, NULL);
					return 3;
				case 'H':  /* Home */
					dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
					dmsg.dwDevMsgParam = VK_HOME;
					DeviceInputManager.SendDeviceMessage(
						(__COMMON_OBJECT*)&DeviceInputManager,
						&dmsg, NULL);
					return 3;
				case 'F':  /* End */
					dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
					dmsg.dwDevMsgParam = VK_END;
					DeviceInputManager.SendDeviceMessage(
						(__COMMON_OBJECT*)&DeviceInputManager,
						&dmsg, NULL);
					return 3;
				case '1':  /* Could be Home or F1-F4 */
					if (length - start_idx >= 4 && buffer[start_idx + 3] == '~') {
						/* Home key (ESC [1~) */
						dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
						dmsg.dwDevMsgParam = VK_HOME;
						DeviceInputManager.SendDeviceMessage(
							(__COMMON_OBJECT*)&DeviceInputManager,
							&dmsg, NULL);
						return 4;
					}
					break;
				case '2':  /* Insert */
					if (length - start_idx >= 4 && buffer[start_idx + 3] == '~') {
						dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
						dmsg.dwDevMsgParam = VK_INSERT;
						DeviceInputManager.SendDeviceMessage(
							(__COMMON_OBJECT*)&DeviceInputManager,
							&dmsg, NULL);
						return 4;
					}
					break;
				case '3':  /* Delete */
					if (length - start_idx >= 4 && buffer[start_idx + 3] == '~') {
						dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
						dmsg.dwDevMsgParam = VK_DELETE;
						DeviceInputManager.SendDeviceMessage(
							(__COMMON_OBJECT*)&DeviceInputManager,
							&dmsg, NULL);
						return 4;
					}
					break;
				case '5':  /* Page Up */
					if (length - start_idx >= 4 && buffer[start_idx + 3] == '~') {
						dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
						dmsg.dwDevMsgParam = VK_PAGEUP;
						DeviceInputManager.SendDeviceMessage(
							(__COMMON_OBJECT*)&DeviceInputManager,
							&dmsg, NULL);
						return 4;
					}
					break;
				case '6':  /* Page Down */
					if (length - start_idx >= 4 && buffer[start_idx + 3] == '~') {
						dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
						dmsg.dwDevMsgParam = VK_PAGEDOWN;
						DeviceInputManager.SendDeviceMessage(
							(__COMMON_OBJECT*)&DeviceInputManager,
							&dmsg, NULL);
						return 4;
					}
					break;
				}
			}
			/* Check for SS3 sequences (ESC O) for function keys */
			else if (buffer[start_idx + 1] == 'O') {
				switch (buffer[start_idx + 2]) {
				case 'P':  /* F1 */
					dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
					dmsg.dwDevMsgParam = VK_F1;
					DeviceInputManager.SendDeviceMessage(
						(__COMMON_OBJECT*)&DeviceInputManager,
						&dmsg, NULL);
					return 3;
				case 'Q':  /* F2 */
					dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
					dmsg.dwDevMsgParam = VK_F2;
					DeviceInputManager.SendDeviceMessage(
						(__COMMON_OBJECT*)&DeviceInputManager,
						&dmsg, NULL);
					return 3;
				case 'R':  /* F3 */
					dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
					dmsg.dwDevMsgParam = VK_F3;
					DeviceInputManager.SendDeviceMessage(
						(__COMMON_OBJECT*)&DeviceInputManager,
						&dmsg, NULL);
					return 3;
				case 'S':  /* F4 */
					dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
					dmsg.dwDevMsgParam = VK_F4;
					DeviceInputManager.SendDeviceMessage(
						(__COMMON_OBJECT*)&DeviceInputManager,
						&dmsg, NULL);
					return 3;
				}
			}
		}
		
		/* Single ESC key press */
		if (length - start_idx >= 1) {
			dmsg.wDevMsgType = KERNEL_MESSAGE_VKEYDOWN;
			dmsg.dwDevMsgParam = VK_ESC;
			DeviceInputManager.SendDeviceMessage(
				(__COMMON_OBJECT*)&DeviceInputManager,
				&dmsg, NULL);
			return 1;
		}
	}
	
	/* Not an escape sequence we recognize */
	return 0;
}

/* 
 * Client request handler thread. 
 * pData contains the socket for the session between
 * the new incoming client and server side, it should
 * be released after save to local(client_sock).
 */
static unsigned long __client_req_handler(LPVOID pData)
{
	int client_sock = *(int*)pData;
	char* welcome_msg = "Welcome to HelloX. Type help for command list.\r\n";
	int ret = 0;
	unsigned char request_buffer[1024];
	char display_buffer[2048];
	int start = -1, disp_buff_len = 0;
	int buffer_len = 1024;
	int buff_rear = 0;
	__DEVICE_MESSAGE dmsg;

	BUG_ON(NULL == pData);
	/* Release the memory. */
	_hx_free(pData);

	int time_out = TELNET_RECV_TIMEOUT;

	if (setsockopt(client_sock, SOL_SOCKET, SO_RCVTIMEO, &time_out, sizeof(int)) < 0) {
		_hx_printf("[%s]set socket option fail\r\n", __func__);
		goto __TERMINAL;
	}

	/* Notify the server manager that a new connection is OK. */
	ttyServer.OnNewConnection(client_sock);

	/* Send a message to the client. */
	ret = send(client_sock, welcome_msg, strlen(welcome_msg), 0);
	if (ret < 0)
	{
		__LOG("[%s]send message fail[%d]\r\n", __func__, ret);
		goto __TERMINAL;
	}

	/* Negotiate session options with client. */
	if (!__negotiate(client_sock))
	{
		_hx_printf("[%s]negotiate options fail.\r\n", __func__);
		goto __TERMINAL;
	}

	/* Main loop of handler. */
	while (TRUE)
	{
		ret = recv(client_sock, request_buffer, buffer_len, 0);
		if (ret > 0)
		{
			/* Process the client's input. */
			for (int i = 0; i < ret; i++)
			{
				/* Check for NVT commands (IAC = 255) */
				if (request_buffer[i] == NVT_IAC)
				{
					/* NVT command. */
					i += __cmd_opt_handler(client_sock, 
						&request_buffer[i], 
						ret - i);
					i--; /* Adjust for loop increment */
					continue;
				}
				
				/* Check for escape sequences (ESC = 0x1B) */
				if (request_buffer[i] == ESC_KEY)
				{
					int esc_len = __handle_escape_sequence(client_sock, 
						request_buffer, ret, i);
					if (esc_len > 0)
					{
						i += esc_len - 1; /* Skip the escape sequence */
						continue;
					}
				}
				
				/* Handle special control keys */
				switch (request_buffer[i])
				{
				case DEL_KEY:  /* Delete key (0x7F) */
					dmsg.wDevMsgType = KERNEL_MESSAGE_AKEYDOWN;
					/* Treat the delete key as backspace. */
					dmsg.dwDevMsgParam = VK_BACKSPACE;
					DeviceInputManager.SendDeviceMessage(
						(__COMMON_OBJECT*)&DeviceInputManager,
						&dmsg, NULL);
					break;
					
				case BS_KEY:   /* Backspace (0x08) */
					dmsg.wDevMsgType = KERNEL_MESSAGE_AKEYDOWN;
					dmsg.dwDevMsgParam = VK_BACKSPACE;
					DeviceInputManager.SendDeviceMessage(
						(__COMMON_OBJECT*)&DeviceInputManager,
						&dmsg, NULL);
					break;
					
				case TAB_KEY:  /* Tab (0x09) */
					dmsg.wDevMsgType = KERNEL_MESSAGE_AKEYDOWN;
					dmsg.dwDevMsgParam = VK_TAB;
					DeviceInputManager.SendDeviceMessage(
						(__COMMON_OBJECT*)&DeviceInputManager,
						&dmsg, NULL);
					break;
					
				case CR_KEY:   /* Carriage return (0x0D) */
					/* Often sent as \r\n, we'll handle both */
					dmsg.wDevMsgType = KERNEL_MESSAGE_AKEYDOWN;
					dmsg.dwDevMsgParam = VK_RETURN;
					DeviceInputManager.SendDeviceMessage(
						(__COMMON_OBJECT*)&DeviceInputManager,
						&dmsg, NULL);
					break;
					
				case LF_KEY:   /* Line feed (0x0A) - usually after CR */
					/* Skip line feed, already handled by CR */
					break;
					
				default:
					/* Regular ASCII character */
					if (request_buffer[i] >= 32 && request_buffer[i] < 127)
					{
						/* Printable ASCII */
						dmsg.wDevMsgType = KERNEL_MESSAGE_AKEYDOWN;
						dmsg.dwDevMsgParam = (unsigned long)request_buffer[i];
						DeviceInputManager.SendDeviceMessage(
							(__COMMON_OBJECT*)&DeviceInputManager,
							&dmsg, NULL);
					}
					/* Note: characters 0-31 are control characters
					   that we might want to handle specially */
					break;
				}
			}
		}

		/* Check the display buffer, and send to client. */
		if (start < 0)
		{
			/* Should use current rear as start. */
			start = DispBufferManager.GetCurrentRear();
		}

		buff_rear = DispBufferManager.buffer_rear;
		if (buff_rear < start)
		{
			/* Delete several keystrokes from buffer. */
			for (int i = 0; i < (start - buff_rear); i++)
			{
				send(client_sock, "\x08 \x08", 3, 0);
			}
			start = buff_rear;
			continue;
		}

		/* Get accumulated bytes in buffer and send to client. */
		while ((disp_buff_len = DispBufferManager.GetBuffer(display_buffer, 2048, &start)) > 0)
		{
			/* Send back to client. */
			ret = send(client_sock, display_buffer, disp_buff_len, 0);
			if (ret < 0)
			{
				__LOG("[%s]send to client fail[%d]\r\n", __func__, ret);
				goto __TERMINAL;
			}
		}
	}

__TERMINAL:
	/* Close the socket. */
	closesocket(client_sock);
	return 0;
}

/*
 * Server thread of TTY, which listens on the server port, then
 * create new thread to handle client's request when received.
 */
static unsigned long __tty_server(LPVOID pData)
{
	int server_sock = -1;
	int *csock_ptr = NULL;
	int ret = 0;
	int client_index = 0;
	char cthread_name[24];
	struct sockaddr_in server_addr;
	struct sockaddr_in client_addr;
	socklen_t sock_len = 0;
	HANDLE hClientThread = NULL;

	__LOG("[%s]tty server start...\r\n", __func__);

	/* Create the server socket. */
	server_sock = socket(AF_INET, SOCK_STREAM, 0);
	if (server_sock < 0)
	{
		__LOG("[%s]create server sock fail[%d].\r\n", __func__, server_sock);
		goto __TERMINAL;
	}

	/* Bind to server port. */
	memset(&server_addr, 0, sizeof(server_addr));
	server_addr.sin_family = AF_INET;
	server_addr.sin_addr.s_addr = INADDR_ANY;
	server_addr.sin_port = htons(TELNET_SERVER_PORT);
	ret = bind(server_sock, (struct sockaddr*)&server_addr, sizeof(server_addr));
	if (ret < 0)
	{
		__LOG("[%s]bind to port fail[%d]\r\n", __func__, ret);
		goto __TERMINAL;
	}

	/* Listen on. */
	ret = listen(server_sock, 5);
	if (ret < 0)
	{
		__LOG("[%s]listen fail[%d]\r\n", __func__, ret);
		goto __TERMINAL;
	}

	__LOG("[%s]wait for connecting...\r\n", __func__);
	while (TRUE)
	{
		/* 
		 * Client socket must be saved in dedicated memory, 
		 * in multiple thread context. It must be released in
		 * client handler thread.
		 */
		csock_ptr = _hx_malloc(sizeof(int));
		if (NULL == csock_ptr)
		{
			_hx_printf("[%s]malloc fail!\r\n", __func__);
			goto __TERMINAL;
		}
		sock_len = sizeof(struct sockaddr_in);
		*csock_ptr = accept(server_sock, (struct sockaddr*)&client_addr, &sock_len);
		if (*csock_ptr < 0)
		{
			__LOG("[%s]accept err[%d]\r\n", __func__, *csock_ptr);
			goto __TERMINAL;
		}

		/* 
		 * New client connection established, show 
		 * general information and create a new
		 * thread to handle this request, then wait again.
		 */
		__LOG("[%s]new request from[%s:%d] established.\r\n", __func__,
			inet_ntoa(client_addr.sin_addr),
			ntohs(client_addr.sin_port));
		/* Contruct a new thread name. */
		_hx_sprintf(cthread_name, "tty_client%d", client_index++);
		/* New a thread to handle this request. */
		hClientThread = CreateKernelThread(
			0,
			KERNEL_THREAD_STATUS_READY,
			PRIORITY_LEVEL_NORMAL,
			__client_req_handler,
			csock_ptr,
			NULL, cthread_name);
		if (NULL == hClientThread)
		{
			_hx_printf("[%s]create client thread fail.\r\n", __func__);
			goto __TERMINAL;
		}
	}

__TERMINAL:
	/* Close the socket if already open. */
	if (server_sock > 0)
	{
		closesocket(server_sock);
	}
	__LOG("[%s]tty server exit with[%d]\r\n", __func__, ret);
	return ret;
}

/* Initialize routine of tty server object. */
static BOOL __Initialize()
{
	HANDLE server_thread = NULL;
	BOOL bResult = FALSE;

	/* Create the server thread. */
	server_thread = CreateKernelThread(0,
		KERNEL_THREAD_STATUS_READY,
		PRIORITY_LEVEL_NORMAL,
		__tty_server,
		NULL, NULL,
		"tty_server");
	if (NULL == server_thread)
	{
		_hx_printf("[%s]create server failed.\r\n", __func__);
		goto __TERMINAL;
	}
	ttyServer.server_thread = server_thread;
	bResult = TRUE;

__TERMINAL:
	return bResult;
}

/* Notify the server that a new connection is established. */
static void __OnNewConnection(int sock)
{
	ttyServer.default_sock = sock;
}

/* Send a byte to the default connection. */
static void __SendChar(char byte)
{
	if (ttyServer.default_sock < 0)
	{
		/* No default connection. */
		return;
	}
	int ret = send(ttyServer.default_sock, &byte, 1, 0);
	if (ret < 0)
	{
		__LOG("[%s]send byte fail[%d]\r\n", __func__, ret);
	}
}

/* Change to a new line. */
static void __ChangeLine()
{
	/* Just send out LF and CR. */
	__SendChar('\r');
	__SendChar('\n');
}

/* Send a string to the client. */
static void __PrintString(const char* string)
{
	if (ttyServer.default_sock < 0)
	{
		/* No default connection. */
		return;
	}
	int ret = send(ttyServer.default_sock, string, strlen(string), 0);
	if (ret < 0)
	{
		__LOG("[%s]send string fail[%d]\r\n", __func__, ret);
	}
}

/* The global tty server object. */
__TTY_SERVER ttyServer = {
	NULL,                //server_thread's handle.
	-1,                  //default_sock.
	__Initialize,        //Initialize routine.
	__OnNewConnection,   //OnNewConnection.
	__SendChar,          //SendChar.
	__ChangeLine,        //ChangeLine.
	__PrintString,       //PrintString.
};
